## What I verified live

I ran a set of probe expressions through the validator/evaluator to ground the recommendations in observed behavior rather than theory:

| Probe | Result | What it tells you |
|---|---|---|
| `(a+b)*2/max(c,1)` (a=3,b=4,c=0) | ✅ valid → `14` | Allowlisted function calls work; the guard clause does its job |
| `__import__("os").system("rm -rf /")` | ❌ rejected (`_` unexpected) | Dunder access never reaches the parser |
| `().__class__.__bases__[0].__subclasses__()` | ❌ rejected | Attribute access + subscript escape is closed |
| `9 ** 9 ** 9 ** 9` | ❌ rejected | **Exponentiation isn't in the grammar at all** — power-tower DoS is impossible by construction |
| `(1 + 2) * (3 - 4` | ❌ rejected | Balance checking works |
| `undefined_var * 2` | ❌ error | Unbound names fail loudly ✅ |
| `1 / 0` | ⚠️ returns `null`, **not** an error | **Silent failure** — a real defect |
| `1e308 * 10` | ⚠️ returns `null`, **not** an error | Float overflow swallowed silently |
| `((((((1+2)))))) * 3` @ `max_depth=2` | ⚠️ **passes** | **Depth limit is not enforced on grouping** |

Two of those are genuine findings worth fixing, and they generalize to any Python `ast`-based evaluator.

---

## Finding 1: `max_depth` cannot see parentheses

CPython's AST **discards** `ParenthesizedExpr`. `ast.parse("((((((1+2))))))")` produces exactly the same tree as `ast.parse("1+2")` — depth 2. So an AST-recursion depth counter will never catch `((((((((...))))))))` nesting, and that input is precisely the shape that blows the C parser's recursive-descent stack (a crash/DoS, not an exception you can catch).

Enforce bracket depth **before** parsing, on the raw characters.

## Finding 2: `1/0` returning `null` is worse than an exception

A `null` result is indistinguishable from a legitimate one. Downstream code either coerces `None → 0` (silent corruption) or crashes somewhere unrelated to the input that caused it. It also means your A09 monitoring never fires, because nothing was logged as a failure. **Fail closed with a typed error.**

---

## Reference implementation

```python
"""Secure evaluation of user-supplied arithmetic expressions."""
from __future__ import annotations

import ast
import logging
import math
import operator
from dataclasses import dataclass

logger = logging.getLogger("mathapi.evaluate")

MAX_LENGTH = 512          # chars — bounds tokenizer work
MAX_BRACKET_DEPTH = 20    # pre-parse, because the AST forgets parens
MAX_NODES = 200           # bounds AST size
MAX_INT_BITS = 256        # ~1.16e77, prevents bigint bombs
MAX_ABS_FLOAT = 1e300     # stays clear of inf/NaN
MAX_ARITY = 8


class ExpressionRejected(ValueError):
    """Input refused by validation. Safe to surface to the caller."""


class EvaluationFailed(RuntimeError):
    """Valid input that could not be computed (e.g. division by zero)."""


_BINARY = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
}
_UNARY = {ast.UAdd: operator.pos, ast.USub: operator.neg}

# name -> (callable, min_args, max_args)
_FUNCTIONS: dict[str, tuple[callable, int, int]] = {
    "abs":   (abs, 1, 1),
    "min":   (min, 1, MAX_ARITY),
    "max":   (max, 1, MAX_ARITY),
    "round": (round, 1, 2),
    "sqrt":  (math.sqrt, 1, 1),
    "floor": (math.floor, 1, 1),
    "ceil":  (math.ceil, 1, 1),
    "log":   (math.log, 1, 2),
}

# Rejected outright — belt-and-braces, the whitelist below already excludes them.
_DENIED = (
    ast.Attribute, ast.Subscript, ast.Lambda, ast.Starred,
    ast.Dict, ast.List, ast.Set, ast.Tuple, ast.JoinedStr,
    ast.Await, ast.Yield, ast.Comprehension, ast.NamedExpr,
)


def _precheck(text: str) -> None:
    """Cheap character-level gate. Runs before the parser ever sees input."""
    if not isinstance(text, str):
        raise ExpressionRejected("expression must be a string")
    if not text.strip():
        raise ExpressionRejected("expression is empty")
    if len(text) > MAX_LENGTH:
        raise ExpressionRejected(f"expression exceeds {MAX_LENGTH} characters")

    depth = 0
    for ch in text:
        if ch in "([{":
            depth += 1
            if depth > MAX_BRACKET_DEPTH:
                raise ExpressionRejected(
                    f"nesting exceeds {MAX_BRACKET_DEPTH} levels"
                )
        elif ch in ")]}":
            depth -= 1
            if depth < 0:
                raise ExpressionRejected("unbalanced brackets")
    if depth != 0:
        raise ExpressionRejected("unbalanced brackets")


def _check_number(value: object) -> None:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ExpressionRejected(
            f"only numeric literals allowed, got {type(value).__name__}"
        )
    if isinstance(value, int):
        if value.bit_length() > MAX_INT_BITS:
            raise ExpressionRejected("integer literal too large")
    else:
        if not math.isfinite(value) or abs(value) > MAX_ABS_FLOAT:
            raise ExpressionRejected("float literal out of range")


def _validate(node: ast.AST, variables: dict[str, float]) -> None:
    """Whitelist walk. Anything not explicitly listed is rejected."""
    for sub in ast.walk(node):
        if isinstance(sub, _DENIED):
            raise ExpressionRejected(
                f"{type(sub).__name__} is not permitted"
            )

    def visit(n: ast.AST) -> None:
        match n:
            case ast.Expression():
                visit(n.body)
            case ast.Constant():
                _check_number(n.value)
            case ast.Name():
                if n.id.startswith("_"):
                    raise ExpressionRejected("private names are not permitted")
                if n.id not in variables:
                    raise ExpressionRejected(f"unknown variable: {n.id}")
            case ast.BinOp():
                if type(n.op) not in _BINARY:
                    raise ExpressionRejected(
                        f"operator {type(n.op).__name__} is not permitted"
                    )
                visit(n.left)
                visit(n.right)
            case ast.UnaryOp():
                if type(n.op) not in _UNARY:
                    raise ExpressionRejected(
                        f"operator {type(n.op).__name__} is not permitted"
                    )
                visit(n.operand)
            case ast.Call():
                if not isinstance(n.func, ast.Name) or n.func.id not in _FUNCTIONS:
                    raise ExpressionRejected("function is not permitted")
                if n.keywords:
                    raise ExpressionRejected("keyword arguments are not permitted")
                _, lo, hi = _FUNCTIONS[n.func.id]
                if not lo <= len(n.args) <= hi:
                    raise ExpressionRejected(
                        f"{n.func.id} expects {lo}-{hi} arguments"
                    )
                for arg in n.args:
                    visit(arg)
            case _:
                raise ExpressionRejected(
                    f"{type(n).__name__} is not permitted"
                )

    visit(node)


def _clamp(value: float) -> int | float:
    """Reject results that escaped the numeric envelope during evaluation."""
    if isinstance(value, int) and value.bit_length() > MAX_INT_BITS:
        raise EvaluationFailed("intermediate result exceeded integer bounds")
    if isinstance(value, float):
        if not math.isfinite(value):
            raise EvaluationFailed("result overflowed to infinity or NaN")
        if abs(value) > MAX_ABS_FLOAT:
            raise EvaluationFailed("result exceeded float bounds")
    return value


def _eval(node: ast.AST, variables: dict[str, float]) -> int | float:
    match node:
        case ast.Expression():
            return _eval(node.body, variables)
        case ast.Constant():
            return node.value
        case ast.Name():
            return variables[node.id]
        case ast.UnaryOp():
            return _clamp(_UNARY[type(node.op)](_eval(node.operand, variables)))
        case ast.BinOp():
            left, right = _eval(node.left, variables), _eval(node.right, variables)
            if isinstance(node.op, (ast.Div, ast.FloorDiv, ast.Mod)) and right == 0:
                raise EvaluationFailed("division by zero")
            return _clamp(_BINARY[type(node.op)](left, right))
        case ast.Call():
            fn, _, _ = _FUNCTIONS[node.func.id]
            args = [_eval(a, variables) for a in node.args]
            try:
                return _clamp(fn(*args))
            except ValueError as exc:       # e.g. sqrt(-1), log(0)
                raise EvaluationFailed(f"invalid argument to {node.func.id}") from exc
        case _:
            raise ExpressionRejected(f"{type(node).__name__} is not permitted")


@dataclass(frozen=True)
class Result:
    expression: str
    value: int | float


def evaluate_expression(
    expression: str, variables: dict[str, float] | None = None
) -> Result:
    """Validate then evaluate. Raises ExpressionRejected or EvaluationFailed."""
    variables = dict(variables or {})
    _precheck(expression)

    try:
        tree = ast.parse(expression, mode="eval")
    except SyntaxError as exc:
        raise ExpressionRejected(f"malformed expression: {exc.msg}") from None

    if sum(1 for _ in ast.walk(tree)) > MAX_NODES:
        raise ExpressionRejected("expression is too complex")

    _validate(tree, variables)
    return Result(expression=expression, value=_eval(tree, variables))
```

### API layer — map failures to distinct status codes

```python
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field

app = FastAPI()


class EvalRequest(BaseModel):
    expression: str = Field(max_length=512)
    variables: dict[str, float] = Field(default_factory=dict, max_length=32)


@app.post("/evaluate")
def evaluate(req: EvalRequest):
    try:
        result = evaluate_expression(req.expression, req.variables)
    except ExpressionRejected as exc:
        # Never echo the raw expression back — it may contain PII or payloads.
        logger.warning("expr_rejected", extra={"reason": str(exc)})
        raise HTTPException(status_code=422, detail=str(exc)) from None
    except EvaluationFailed as exc:
        logger.info("expr_failed", extra={"reason": str(exc)})
        raise HTTPException(status_code=400, detail=str(exc)) from None
    return {"value": result.value}
```

Note the split: `422` means *"your input was refused"*, `400` means *"your math didn't work"*. Clients can retry the second, never the first. Both are logged; neither leaks

## Short answer

Never `eval()` user math. Parse it with `ast.parse(mode="eval")` and then **walk the tree with an explicit allowlist of node types**, evaluating it yourself with your own numeric namespace and hard resource limits. Everything else — length caps, depth caps, numeric-type normalization, error hygiene, rate limiting — is defense in depth around that core.

## What the validation probes showed

| Probe | Result |
|---|---|
| `__import__('os').system('rm -rf /')` | **Rejected** — "Unexpected character `_` at line 1, column 1" |
| `(rate * months) / 12 + sqrt(principal)` with variables allowed | Valid |
| `(1500 * 24) / 12 + sqrt(14400)` | `3120` (number) |

Two lessons worth taking into your code:

1. **A strict grammar kills the classic payload cheaply.** Blocking `_`, `.`, brackets other than `()`, and quotes at the character level eliminates attribute access, dunders, subscripts, and string literals before any parsing happens. Do this *first* as a cheap rejection layer, but not as your *only* layer.
2. **Don't trust a `max_depth`-style knob without testing it.** I passed 9 levels of nested parentheses with `max_depth=5` and the validator still returned "syntactically valid." Depth limits need to be enforced in *your* AST walk, where you can actually count — see the drop-in below.

## The core: an allowlist AST evaluator

```python
import ast, operator, re, math
from decimal import Decimal

MAX_LEN      = 512      # characters
MAX_NODES    = 200      # AST node budget
MAX_DEPTH    = 20       # nesting depth
MAX_DIGITS   = 1000     # int digit ceiling
MAX_EXPONENT = 1000

# Cheap pre-filter: only numbers, operators, parens, commas, spaces
SAFE_CHARS = re.compile(r"^[0-9eE\.\+\-\*/%\(\)\,\s]*$")

BIN_OPS = {ast.Add: operator.add, ast.Sub, ast.Mult: operator.mul,
           ast.Div: operator.truediv, ast.FloorDiv: operator.floordiv,
           ast.Mod: operator.mod, ast.Pow: operator.pow}
UNARY_OPS = {ast.UAdd: operator.pos, ast.USub: operator.neg}

FUNCS = {                     # name -> (callable, min_args, max_args)
    "sqrt": (math.sqrt, 1, 1), "log": (math.log, 1, 2),
    "exp": (math.exp, 1, 1),   "abs": (abs, 1, 1),
    "min": (min, 1, 10),       "max": (max, 1, 10),
    "round": (round, 1, 2),
}

class ExpressionRejected(ValueError):
    """Raised for any policy violation. Never leak internals to the client."""

def _check_numeric(value):
    if isinstance(value, bool):
        raise ExpressionRejected("boolean not permitted in arithmetic")
    if not isinstance(value, (int, float, Decimal)):
        raise ExpressionRejected("non-numeric operand")
    if isinstance(value, float) and (math.isnan(value) or math.isinf(value)):
        raise ExpressionRejected("non-finite result")
    if isinstance(value, int) and abs(value).bit_length() > MAX_DIGITS * 3.33:
        raise ExpressionRejected("integer too large")
    return value

def evaluate(expr: str, variables: dict[str, float] | None = None):
    if not isinstance(expr, str) or len(expr) > MAX_LEN:
        raise ExpressionRejected("expression too long")
    if not SAFE_CHARS.match(expr):
        raise ExpressionRejected("illegal character")

    try:
        tree = ast.parse(expr, mode="eval")
    except SyntaxError:
        raise ExpressionRejected("malformed expression") from None

    if sum(1 for _ in ast.walk(tree)) > MAX_NODES:
        raise ExpressionRejected("expression too complex")

    variables = variables or {}

    def walk(node, depth):
        if depth > MAX_DEPTH:
            raise ExpressionRejected("nesting too deep")

        if isinstance(node, ast.Expression):
            return walk(node.body, depth + 1)
        if isinstance(node, ast.Constant):
            return _check_numeric(node.value)
        if isinstance(node, ast.BinOp):
            op = BIN_OPS.get(type(node.op))
            if op is None:
                raise ExpressionRejected("operator not allowed")
            left, right = walk(node.left, depth + 1), walk(node.right, depth + 1)
            if isinstance(node.op, ast.Pow) and abs(right) > MAX_EXPONENT:
                raise ExpressionRejected("exponent too large")
            return _check_numeric(op(left, right))
        if isinstance(node, ast.UnaryOp):
            op = UNARY_OPS.get(type(node.op))
            if op is None:
                raise ExpressionRejected("unary operator not allowed")
            return _check_numeric(op(walk(node.operand, depth + 1)))
        if isinstance(node, ast.Name):
            if node.id not in variables:
                raise ExpressionRejected("unknown variable")
            return _check_numeric(variables[node.id])
        if isinstance(node, ast.Call):
            if not isinstance(node.func, ast.Name) or node.keywords:
                raise ExpressionRejected("unsupported call form")
            spec = FUNCS.get(node.func.id)
            if spec is None:
                raise ExpressionRejected("function not allowed")
            fn, lo, hi = spec
            if not lo <= len(node.args) <= hi:
                raise ExpressionRejected("wrong argument count")
            args = [walk(a, depth + 1) for a in node.args]
            return _check_numeric(fn(*args))

        # Everything else — Attribute, Subscript, Lambda, comprehension,
        # IfExp, Starred, Dict, JoinedStr, Await... — is denied by default.
        raise ExpressionRejected(f"node type not allowed: {type(node).__name__}")

    return walk(tree, 0)
```

The key structural point: **it's a default-deny dispatch**, not a blocklist. `ast.Attribute`, `ast.Subscript`, `ast.Lambda`, `ast.JoinedStr` (f-strings), and comprehensions all fall through to the final `raise` without you naming them. New Python syntax added in future versions is denied automatically.

